use actix_web::{web, App, HttpResponse, HttpServer, Responder, post};
use actix_multipart::Multipart;
use futures_util::stream::StreamExt as _;
use std::io::Write;
use tempdir::TempDir;
use std::process::Command;

#[post("/convert")]
async fn convert_pdf(mut payload: Multipart) -> impl Responder {
    let temp_dir = TempDir::new("pdf_to_text").unwrap();
    let temp_file_path = temp_dir.path().join("uploaded.pdf");

    while let Some(item) = payload.next().await {
        let mut field = item.unwrap();
        let mut file = std::fs::File::create(&temp_file_path).unwrap();

        while let Some(chunk) = field.next().await {
            let data = chunk.unwrap();
            file.write_all(&data).unwrap();
        }
    }

    let output = Command::new("pdftotext")
        .arg(&temp_file_path)
        .arg("-")
        .output();

    match output {
        Ok(output) => {
            if output.status.success() {
                let text = String::from_utf8_lossy(&output.stdout);
                HttpResponse::Ok().content_type("text/plain").body(text)
            } else {
                HttpResponse::InternalServerError().body("Conversion failed")
            }
        }
        Err(_) => HttpResponse::InternalServerError().body("Conversion failed"),
    }
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    env_logger::init();
    HttpServer::new(|| {
        App::new()
            .service(convert_pdf)
    })
    .bind("0.0.0.0:5000")?
    .run()
    .await
}
```
